/**
 * TEST ONLY. 4D-SCP v0.1.12 — vector, relation-program and simulator-input generation for the RTL
 * event-driven relations decoder (hw/scp4d/rtl/scp4d_rdec.v). Pure: no I/O, no env, no clocks,
 * no randomness.
 *
 * - New relations golden vectors (rank 0, relations on, last-value hold) are GENERATED by the
 *   v0.1.10 integer model (scripts/scp-v0110-int-scp4d.ts: encodeIntScp4d + decodeIntScp4d), never
 *   hand-edited.
 * - The v0.1.10 report's "event-driven +relations" environment streams (env-16x16x2-T64 / T256)
 *   are regenerated deterministically; the check pins their size and sha256 prefix against
 *   fixtures/scp/v0110-int-report.json.
 * - rtlProgram(): the relation program the RTL loads through its cfg port, built from the model's
 *   own fixed-point setup (fixRelations output) with the model's processing order (makePlan:
 *   non-targets ascending, then targets ascending) and fan-out order (relation index, then source
 *   index). Host-side setup, like the model's; not part of the per-element datapath.
 * - rdecCycleModel(): closed-form cycle count of scp4d_rdec as designed. The check compares it with
 *   the simulator's measured count, so the committed report can be re-verified without a simulator.
 */
import type { Relation4D, StateSurface4D } from "../src/scp/subsystem";
import { ENV_EPS, ENV_LABEL, FRAME_EPS, frameFixtures, makeEnvironment } from "./scp-v019-env-fixture";
import {
  DECLARED_WIDTHS, DEFAULT_G, decodeIntScp4d, encodeIntScp4d, fixRelations, ingestCodes, signedBits,
  type Census, type FrameEvents, type IntConfig, type IntRelation, type IntStreamInput, type RegName,
} from "./scp-v0110-int-scp4d";
import { streamStructure, type StreamStructure } from "./scp-v0111-rtl-vectors";

/** RTL parameters (must match scp4d_rdec.v defaults; the check verifies). */
export const RDEC = { ADDR_W: 11, REL_W: 10, FAN_W: 11, FC_W: 4 } as const;
export const RDEC_MAX_D = 2 ** RDEC.ADDR_W;
export const RDEC_MAX_REL = 2 ** RDEC.REL_W;
export const RDEC_MAX_FAN = 2 ** RDEC.FAN_W;
export const RDEC_MAX_FC = 2 ** RDEC.FC_W - 1;
/** Frame-end settle cycles before the dirty-target flush (relations streams only). */
export const RDEC_FW = 4;
/** Cycles from the last op issued to `done` observed (stages M, A, B, out, done). */
export const RDEC_DRAIN = 5;
const AUX_W = Math.max(RDEC.REL_W, RDEC.FAN_W);

// ---------- relation program ----------
export interface RtlProgram {
  D: number; nT: number; nnt: number; fanEntries: number;
  order: number[];              // processing position -> element
  targetIdx: number[];          // element -> relation index or -1
  fanCount: number[];           // element -> fan-out entries
  fanTargets: number[][];       // element -> relation indices (fan-out order)
  words: bigint[];              // config writes {sel[3:0], addr[15:0], data[47:0]}
  maxFanPerSource: number;
}
const cw = (sel: number, addr: number, data: bigint): bigint => (BigInt(sel) << BigInt(64)) | (BigInt(addr) << BigInt(48)) | (data & ((BigInt(1) << BigInt(48)) - BigInt(1)));
const twos = (v: number, bits: number): bigint => { const b = BigInt(v); return b < 0 ? (BigInt(1) << BigInt(bits)) + b : b; };

/** Build the RTL relation program from the model's fixed-point relations. rels = [] gives a program with nT = 0. */
export function rtlProgram(D: number, rels: readonly IntRelation[]): RtlProgram {
  if (D < 1 || D > RDEC_MAX_D) throw new RangeError("D outside the RTL range");
  if (rels.length > RDEC_MAX_REL) throw new RangeError("too many relations for the RTL");
  const targetIdx = new Array<number>(D).fill(-1);
  const fan: { ti: number; W: number }[][] = Array.from({ length: D }, () => []);
  rels.forEach((r, i) => {
    if (r.target < 0 || r.target >= D) throw new RangeError("relation target outside the frame");
    if (targetIdx[r.target] >= 0) throw new RangeError("duplicate relation target (not supported by the RTL program)");
    targetIdx[r.target] = i;
  });
  rels.forEach((r, i) => r.sources.forEach((s, j) => {
    if (targetIdx[s] >= 0) throw new RangeError("a relation target is also a source (not supported by the RTL)");
    fan[s].push({ ti: i, W: r.W[j] });
  }));
  const order: number[] = [];
  for (let e = 0; e < D; e++) if (targetIdx[e] < 0) order.push(e);
  for (let e = 0; e < D; e++) if (targetIdx[e] >= 0) order.push(e);
  const words: bigint[] = [cw(3, 0, BigInt(D)), cw(3, 1, BigInt(rels.length))];
  const start = new Array<number>(D).fill(0);
  const fanWords: bigint[] = [];
  let maxFan = 0;
  for (let e = 0; e < D; e++) {
    if (targetIdx[e] >= 0 || fan[e].length === 0) continue;
    if (fan[e].length > RDEC_MAX_FC) throw new RangeError("fan-out per source exceeds the RTL count field");
    maxFan = Math.max(maxFan, fan[e].length);
    start[e] = fanWords.length;
    for (const f of fan[e]) {
      if (signedBits(Math.abs(f.W)) > DECLARED_WIDTHS.weight) throw new RangeError("weight exceeds 18 bits");
      const tg = rels[f.ti].target;
      fanWords.push((BigInt(tg) << BigInt(RDEC.REL_W + 18)) | (BigInt(f.ti) << BigInt(18)) | twos(f.W, 18));
    }
  }
  if (fanWords.length > RDEC_MAX_FAN) throw new RangeError("too many fan-out entries for the RTL");
  order.forEach((e, i) => {
    const tgt = targetIdx[e] >= 0;
    const aux = tgt ? targetIdx[e] : start[e];
    const cnt = tgt ? 0 : fan[e].length;
    const word = (BigInt(tgt ? 1 : 0) << BigInt(RDEC.ADDR_W + AUX_W + RDEC.FC_W)) | (BigInt(e) << BigInt(AUX_W + RDEC.FC_W)) | (BigInt(aux) << BigInt(RDEC.FC_W)) | BigInt(cnt);
    words.push(cw(0, i, word));
  });
  fanWords.forEach((w, j) => words.push(cw(1, j, w)));
  rels.forEach((r, i) => {
    if (signedBits(Math.abs(r.bias)) > DECLARED_WIDTHS.rel_acc) throw new RangeError("bias exceeds 48 bits");
    words.push(cw(2, i, twos(r.bias, 48)));
  });
  return {
    D, nT: rels.length, nnt: D - rels.length, fanEntries: fanWords.length, order, targetIdx,
    fanCount: fan.map((f, e) => (targetIdx[e] >= 0 ? 0 : f.length)), fanTargets: fan.map((f) => f.map((x) => x.ti)),
    words, maxFanPerSource: maxFan,
  };
}
export const programHex = (p: RtlProgram): string => p.words.map((w) => w.toString(16).padStart(17, "0")).join("\n") + "\n";

// ---------- vectors ----------
export interface RelationsVector {
  id: string; note: string; label: string;
  shape: { nx: number; ny: number; nz: number; channels: number };
  eps_f64_bits: string[]; G: number; config: IntConfig;
  times: number[]; meta: unknown;
  relations_fixed_point: IntRelation[];
  processing_order: number[];
  rtl_program_hex: string[];
  input_codes: number[][];
  expected_bytes_hex: string;
  expected_decoded_codes: number[][];
  expected_events: { positions: number[]; q: number[]; dense: boolean }[];
  register_max_abs: Record<string, number>;
  register_max_bits: Record<string, number>;
  decode_ops: Record<string, number>;
}

const bitsHex = (v: number) => { const b = Buffer.alloc(8); b.writeDoubleLE(v); return Buffer.from(b).reverse().toString("hex"); };
const hex = (b: Uint8Array) => Buffer.from(b).toString("hex");
const widthsOf = (c: Record<string, number>) => Object.fromEntries(Object.keys(c).map((k) => [k, c[k] === 0 ? 0 : signedBits(c[k])]));
const inputOf = (s: StateSurface4D, eps: number[]): IntStreamInput => ({ shape: s.shape, times: s.times, meta: s.meta, eps, relations: s.relations });
const D_OF = (s: StateSurface4D) => s.shape.nx * s.shape.ny * s.shape.nz * s.shape.channels;

/** Same hand-written values as the v0.1.10 / v0.1.11 edge vector (non-zero bias: 0.25). */
function edgeSurface(): StateSurface4D {
  const vals = [[0, 0.25], [1.37, 0.95], [-2.5, -1.0], [-2.49, -1.0], [3.0, 1.75], [3.0, 1.74], [-0.004, 0.249]];
  const relations: Relation4D[] = [{ target: 1, sources: [0], weights: [0.5], bias: 0.25, kind: "ch1 = 0.5·ch0 + 0.25" }];
  return { shape: { nx: 1, ny: 1, nz: 1, channels: 2 }, channelNames: ["a", "b"], times: vals.map((_, i) => 1_000 + 10 * i),
    frames: vals.map((v) => Float64Array.from(v)), relations, label: "TEST-ONLY hand-written edge cases (negatives, large jumps, near-threshold holds, bias)" };
}
function sliceSurface(s: StateSurface4D, T: number, label: string): StateSurface4D {
  return { ...s, times: s.times.slice(0, T), frames: s.frames.slice(0, T), meta: s.meta ? { steps: s.meta.steps.slice(0, T), verdicts: s.meta.verdicts.slice(0, T) } : undefined, label };
}

type Spec = { id: string; note: string; label: string; surface: StateSurface4D; eps: number[]; cfg: IntConfig };
const REL_LAST = (G = DEFAULT_G): IntConfig => ({ rank: 0, relations: true, predictor: "last", G });

function specs(): Spec[] {
  const ff = frameFixtures();
  const v01 = ff.find((f) => f.name === "v0.1")!, med = ff.find((f) => f.name === "A-medicare")!, b256 = ff.find((f) => f.name === "B256")!;
  const env8 = makeEnvironment({ nx: 8, ny: 8, nz: 1, T: 16 });
  return [
    { id: "v0.1-first-16-relations-last", note: "First 16 frames of the v0.1 fixture; relations (observed ~ predicted) + last-value hold; all-dense layout (D=3).", label: "TEST-ONLY hand-written v0.1 fixture (first 16)", surface: sliceSurface(v01.surfaceRel, 16, "TEST-ONLY hand-written v0.1 fixture (first 16)"), eps: [...FRAME_EPS], cfg: REL_LAST() },
    { id: "medicare-6-relations-last", note: "The 6-row Medicare-shaped test fixture; relations + last-value hold.", label: med.surfaceRel.label, surface: med.surfaceRel, eps: [...FRAME_EPS], cfg: REL_LAST() },
    { id: "B256-relations-last", note: "Seeded noisy fixture N=256 (D=3, T=256); relations + last-value hold; all-dense layout.", label: b256.surfaceRel.label, surface: b256.surfaceRel, eps: [...FRAME_EPS], cfg: REL_LAST() },
    { id: "edge-handwritten-G2-relations-last", note: "The hand-written edge values at G=2 with a NON-ZERO relation bias (0.25); relations + last-value hold.", label: "TEST-ONLY hand-written", surface: edgeSurface(), eps: [0.01, 0.01], cfg: REL_LAST(2) },
    { id: "env-8x8x1-T16-relations-last", note: "SYNTHETIC environment 8x8x1 (D=256), 16 frames; relations + last-value hold; adaptive sparse/dense frames.", label: ENV_LABEL, surface: env8.surface, eps: [...ENV_EPS], cfg: REL_LAST() },
  ];
}

function build(s: Spec): RelationsVector & { _ok: boolean } {
  const codes = ingestCodes(s.surface.frames, s.surface.shape.channels, s.eps, s.cfg.G);
  const r = encodeIntScp4d(inputOf(s.surface, s.eps), codes, s.cfg);
  if (r.cfg.rank !== 0 || !r.cfg.relations || r.cfg.predictor !== "last") throw new RangeError(`${s.id}: not a rank-0 relations last-value stream`);
  const d = decodeIntScp4d(r.bytes, s.surface.relations, { verifyAccumulators: true });
  const cen = Object.fromEntries((Object.keys(DECLARED_WIDTHS) as RegName[]).map((k) => [k, Math.max(r.census[k], d.census[k])])) as Census;
  const prog = rtlProgram(D_OF(s.surface), r.rels);
  return {
    id: s.id, note: s.note, label: s.label, shape: s.surface.shape, eps_f64_bits: s.eps.map(bitsHex), G: r.cfg.G, config: r.cfg,
    times: [...s.surface.times], meta: s.surface.meta ?? null,
    relations_fixed_point: r.rels.map((x) => ({ target: x.target, sources: [...x.sources], W: [...x.W], bias: x.bias })),
    processing_order: [...prog.order],
    rtl_program_hex: programHex(prog).trim().split("\n"),
    input_codes: codes.map((f) => Array.from(f)),
    expected_bytes_hex: hex(r.bytes),
    expected_decoded_codes: d.codes.map((f) => Array.from(f)),
    expected_events: d.perFrame.map((f) => ({ positions: f.positions, q: f.q, dense: f.dense })),
    register_max_abs: cen, register_max_bits: widthsOf(cen),
    decode_ops: { ...d.ops },
    _ok: d.codes.every((f, t) => f.every((x, e) => x === r.decoded[t][e])) && JSON.stringify(d.plan.order) === JSON.stringify(prog.order),
  };
}

export const RELATIONS_VECTORS_FORMAT = "4d-scp-v0.1.12-scp4d-int-relations-golden-vectors";
export function relationsVectorFile(): { file: object; ok: boolean; vectors: RelationsVector[] } {
  const built = specs().map(build);
  const vectors = built.map(({ _ok, ...v }) => v);
  return {
    ok: built.every((v) => v._ok),
    vectors,
    file: {
      format: RELATIONS_VECTORS_FORMAT,
      version: 1,
      note: "TEST ONLY. Bit-accurate reference vectors for the v0.1.12 RTL relations decoder (rank 0, relations on, last-value hold). Generated by the v0.1.10 integer model (scripts/scp-v0110-int-scp4d.ts), not hand-edited; rtl_program_hex is the relation program the RTL loads (built from the model's fixed-point setup by scripts/scp-v0112-rtl-vectors.ts rtlProgram). Inputs are labelled test fixtures, not production data. Same S4DI v1 stream format as fixtures/scp/golden-vectors-scp4d.json (unchanged).",
      generator: "scripts/scp-v0112-rtl-vectors.ts (relationsVectorFile)",
      program_word: "17 hex digits = {sel[3:0], addr[15:0], data[47:0]}; sel 0 ORD {is_target, e[10:0], aux[10:0], fan_cnt[3:0]}, 1 FAN {tg[10:0], ti[9:0], W[17:0]}, 2 ACC (bias, 48-bit two's complement), 3 regs (addr 0 D, addr 1 nT)",
      vectors,
    },
  };
}

/** The v0.1.10 report's "event-driven +relations" environment streams (rank 0, last), regenerated. */
export function envRelationsStreams(): { id: string; T: number; D: number; bytes: Uint8Array; codes: number[][]; perFrame: FrameEvents[]; rels: IntRelation[]; decode_ops: Record<string, number> }[] {
  return [64, 256].map((T) => {
    const s = makeEnvironment({ nx: 16, ny: 16, nz: 2, T }).surface;
    const cfg = REL_LAST();
    const codes = ingestCodes(s.frames, s.shape.channels, [...ENV_EPS], cfg.G);
    const r = encodeIntScp4d(inputOf(s, [...ENV_EPS]), codes, cfg);
    const d = decodeIntScp4d(r.bytes, s.relations);
    return { id: `env-16x16x2-T${T}-relations-last`, T, D: codes[0].length, bytes: r.bytes, codes: d.codes.map((f) => Array.from(f)), perFrame: d.perFrame, rels: r.rels, decode_ops: { ...d.ops } };
  });
}

/** Relation fixed point for a surface + eps + G (host setup), for programs of vectors read from files. */
export const relationsOf = (relations: readonly Relation4D[], shape: StateSurface4D["shape"], eps: readonly number[], G: number): IntRelation[] => fixRelations(relations, shape, eps, G);

// ---------- stream walk + RTL cycle model ----------
function readU(buf: Uint8Array, i: number): [number, number] {
  let n = 0, s = 0;
  for (;;) { const b = buf[i++]; n += (b & 0x7f) * 2 ** s; if ((b & 0x80) === 0) return [n, i]; s += 7; }
}
/** Event processing positions per frame of an S4DI v1 rank-0 stream. */
export function eventPositions(buf: Uint8Array, s: StreamStructure): number[][] {
  let i = s.fixed_bytes + s.header_tail_bytes;
  const allDense = buf[i - 1] === 1;
  const out: number[][] = [];
  for (let t = 0; t < s.T; t++) {
    let isDense = true, n = 0;
    if (!allDense) { const [h, j] = readU(buf, i); i = j; n = Math.floor(h / 2); isDense = h % 2 === 1; }
    const pos: number[] = [];
    if (isDense) for (let p = 0; p < s.D; p++) { const [u, j] = readU(buf, i); i = j; if (u !== 0) pos.push(p); }
    else { let p = -1; for (let k = 0; k < n; k++) { const [g, j] = readU(buf, i); i = j; p = k === 0 ? g : p + 1 + g; pos.push(p); i = readU(buf, i)[1]; } }
    out.push(pos);
  }
  if (i !== buf.length) throw new RangeError("event walk did not end at the last byte");
  return out;
}

export interface RdecCycleModel {
  cycles: number; bytes: number; clear_stall: number; fan_cycles: number; settle_cycles: number; flush_cycles: number; drain: number;
  source_events: number; target_events: number; dirty_per_frame: number[];
}
/**
 * Cycle model of scp4d_rdec (full-rate input, no bubbles), counted like the testbench: from the
 * first cycle after reset to the cycle `done` is observed, inclusive.
 *   cycles = bytes + max(0, D − header_tail_bytes) + fan + [relations] T·FW + flush + DRAIN
 *   fan    = Σ over non-target events of the element's fan-out entry count (one ACC update per cycle)
 *   flush  = nT (frame 0: every target) + Σ_{t ≥ 1} |dirty targets of frame t|
 */
export function rdecCycleModel(buf: Uint8Array, prog: RtlProgram | null): RdecCycleModel {
  const s = streamStructure(buf);
  const clear_stall = Math.max(0, s.D - s.header_tail_bytes);
  const rel = s.relations === 1;
  const pos = eventPositions(buf, s);
  let fan = 0, srcEv = 0, tgtEv = 0, flush = 0;
  const dirtyPerFrame: number[] = [];
  pos.forEach((ps, t) => {
    const dirty = new Set<number>();
    for (const p of ps) {
      if (!rel || !prog) continue;
      const e = prog.order[p];
      const ti = prog.targetIdx[e];
      if (ti >= 0) { tgtEv++; dirty.add(ti); }
      else if (prog.fanCount[e] > 0) { srcEv++; fan += prog.fanCount[e]; for (const x of prog.fanTargets[e]) dirty.add(x); }
    }
    if (rel && prog) { const f = t === 0 ? prog.nT : dirty.size; flush += f; dirtyPerFrame.push(dirty.size); }
  });
  const settle = rel ? s.T * RDEC_FW : 0;
  return { cycles: s.bytes + clear_stall + fan + settle + flush + RDEC_DRAIN, bytes: s.bytes, clear_stall, fan_cycles: fan, settle_cycles: settle, flush_cycles: flush, drain: RDEC_DRAIN,
    source_events: srcEv, target_events: tgtEv, dirty_per_frame: dirtyPerFrame };
}

// ---------- simulator inputs ----------
const w32 = (v: number) => ((v < 0 ? v + 2 ** 32 : v) >>> 0).toString(16).padStart(8, "0");
export function rdecSimFiles(bytes: Uint8Array, codes: readonly (readonly number[])[], eventsPerFrame: readonly number[], prog: RtlProgram): { stream: string; codes: string; events: string; prog: string; nprog: number } {
  for (const f of codes) for (const v of f) if (!Number.isInteger(v) || v < -(2 ** 31) || v >= 2 ** 31) throw new RangeError("code outside 32-bit");
  return {
    stream: Array.from(bytes, (b) => b.toString(16).padStart(2, "0")).join("\n") + "\n",
    codes: codes.length ? codes.flatMap((f) => f.map(w32)).join("\n") + "\n" : "00000000\n",
    events: eventsPerFrame.length ? eventsPerFrame.map(w32).join("\n") + "\n" : "00000000\n",
    prog: programHex(prog), nprog: prog.words.length,
  };
}
